# Define "perfect" shapes
# Hollow square: 8 cells forming 3x3 with center empty
# T-tetromino: 4 cells forming cross-like T pattern

def is_hollow_square(cells, bbox):
    min_r, min_c, max_r, max_c = bbox
    if max_r - min_r != 2 or max_c - min_c != 2:
        return False  # Should be 3x3

    if len(cells) != 8:
        return False

    inner = (min_r+1, min_c+1)
    if inner in cells:
        return False

    # All boundary cells should be present
    for r in range(min_r, max_r+1):
        for c in range(min_c, max_c+1):
            cell = (r, c)
            if cell == inner:
                continue  # OK that it's missing
            if cell not in cells:
                return False
    return True

def is_tetromino(cells, bbox):
    """Check for T-tetromino pattern"""
    if len(cells) != 4:
        return False

    if max_r := max(r for r,c in cells) - min(r for r,c in cells) > 1:
        return False
    if max_c := max(c for r,c in cells) - min(c for r,c in cells) > 1:
        return False

    # Find potential center (cell with 3 orthogonal neighbors in other cells)
    neighbor_count = {c: 0 for c in cells}
    for r, c in cells:
        for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
            n = (r+dr, c+dc)
            if n in cells:
                neighbor_count[c] += 1

    centers = [(r,c) for (r,c), cnt in neighbor_count.items() if cnt == 3]
    if not centers:
        return False

    center = centers[0]
    # Check all cells adjacent to center orthogonally
    directions = set()
    for r, c in cells:
        if r == center[0] and abs(c - center[1]) == 1:
            directions.add('left_right')
        elif abs(r - center[0]) == 1 and c == center[1]:
            directions.add('up_down')

    return 'left_right' in directions and 'up_down' in directions

