def check_hollow_square(cells):
    """3x3 frame with center empty = 8 cells"""
    if len(cells) != 8:
        return False
    min_r, max_r = min(r for r,_ in cells), max(r for r,_ in cells)
    min_c, max_c = min(c for _,c in cells), max(c for _,c in cells)
    # Should be 3x3 bounding box
    if max_r - min_r + 1 != 3 or max_c - min_c + 1 != 3:
        return False
    # Check all perimeter cells exist
    expected = []
    for dr in range(3):
        for dc in range(3):
            if dr == 0 or dr == 2 or dc == 0 or dc == 2:
                expected.append((min_r + dr, min_c + dc))
    return set(cells) == set(expected)

def check_cross_tetromino(cells):
    """Plus sign / T-tetromino = 5 cells, cross shape"""
    if len(cells) != 5:
        return False
    min_r, max_r = min(r for r,_ in cells), max(r for r,_ in cells)
    min_c, max_c = min(c for _,c in cells), max(c for _,c in cells)
    # Should be 3x3 bounding box  
    if max_r - min_r + 1 != 3 or max_c - min_c + 1 != 3:
        return False
    # Check exact cross pattern: center+4 neighbors
    center = (min_r + 1, min_c + 1)
    if center not in cells:
        return False
    expected = [center, 
                (min_r, min_c + 1), (max_r, min_c + 1),  # top/bottom of stem
                (min_r + 1, min_c), (min_r + 1, max_c)]  # left/right of bar
    return set(cells) == set(expected)

