    if len(r1_cells) != 3 or len(r2_cells) != 3:
        return False
    if len(r3_cells) != 1:
        return False

    # Top row: cols 0,1,2 (relative)
    # Second row: cols 0,1,2
    # Third row: only center col 1
    return True

def check_diamond(cells):
    """Diamond/X shape = 5 cells"""
    if len(cells) != 5:
        return False
    min_r, max_r = min(r for r,_ in cells), max(r for r,_ in cells)
    min_c, max_c = min(c for _,c in cells), max(c for _,c in cells)
    # Bounding box
    if max_r - min_r + 1 != 3 or max_c - min_c + 1 != 3:
        return False

    # Pattern: corners + center
    # X.X / .X. / X.X (using relative coords where 0 = top-left of bbox)
    expected = [(min_r, min_c),   # top-left corner
                (min_r, max_c),   # top-right corner  
                (max_r, min_c),   # bottom-left corner
                (max_r, max_c),   # bottom-right corner
                (min_r + 1, min_c + 1)]  # center
    return set(cells) == set(expected)

