    def reflect_x(c):
        return ((r, -c) for r,c in cells)

    # Get bounding box and normalize
    orig = tuple(sorted(cells))

    orientations = [orig]
    current = list(orig)

    # 4 rotations
    for _ in range(4):
        current = sorted(rotate90(current))
        orientations.append(tuple(current))

    # Add reflected versions of each rotation
    for rot in orientations:
        reflected = sorted(reflect_x(rot))
        orientations.append(tuple(reflected))

    # Remove duplicates
    return set(orientations)

def matches_pattern(cells, target_sig):
    """Check if cells match target after any transformation"""
    all_orients = get_all_orientations(cells)
    return any(o == target_sig for o in all_orients)

